package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;

public class DirectVoiceDownloadTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier condition,String message,long timeout)throws Exception{long until=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<until){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(condition.getAsBoolean()));if(ready.get())return;Thread.sleep(100);}throw new AssertionError(message);}
    boolean containsText(View view,String value){if(view instanceof TextView&&((TextView)view).getText().toString().equals(value))return true;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)if(containsText(group.getChildAt(i),value))return true;}return false;}
    void screenshot(String name)throws Exception{waitForIdleSync();android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    public void onCreate(Bundle state){super.onCreate(state);start();}
    public void onStart(){Bundle result=new Bundle();OfflineVoicesActivity activity=null;Context context=getTargetContext();Map<String,?> preferences=new HashMap<>(context.getSharedPreferences("reading_settings",0).getAll());boolean passed=false;try{check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for direct download verification");activity=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity a=activity;await(()->a.system!=null&&a.system.initialized,"engines not ready",35000);ui(()->{check(a.headers.size()==15,"lost language rows");check(!containsText(a.root,a.getString(R.string.speech_settings)),"system speech settings button remains");});String candidate="";for(String language:new String[]{"de","ko","es","pt","ru","ar","hi","id","vi","th","zh-Hant"})if(a.items(language).isEmpty()&&a.downloadable("com.google.android.tts",language)!=null){candidate=language;break;}check(!candidate.isEmpty(),"no uninstalled Google offline package available for verification");final String language=candidate;result.putString("language",language);ui(()->{a.expanded=language;a.render();a.engineButtons.get("com.google.android.tts:"+language).performClick();check(a.pending("com.google.android.tts",language),"engine download was not recorded");check(a.visible&&a.hasWindowFocus(),"download opened an external page");check(a.previewKey.isEmpty()&&!a.guard.held,"download started audio or stole focus");});waitForIdleSync();ui(()->{View group=(View)a.headers.get(language).getParent().getParent().getParent();a.scroll.scrollTo(0,group.getTop());});screenshot("voice-direct-downloading.png");long until=SystemClock.elapsedRealtime()+180000;while(SystemClock.elapsedRealtime()<until){AtomicBoolean done=new AtomicBoolean();ui(()->{check(a.visible,"engine left app during download");done.set(!a.items(language).isEmpty()&&!a.pending("com.google.android.tts",language));});if(done.get())break;Thread.sleep(1000);}ui(()->{check(!a.items(language).isEmpty()&&!a.pending("com.google.android.tts",language),"engine has not installed the requested voice data");check(!containsText(a.root,a.getString(R.string.speech_settings)),"settings button returned");check(context.getSharedPreferences("reading_settings",0).getAll().equals(preferences),"download changed reading preferences");});OfflineVoicesActivity.Item item=a.items(language).get(0);ui(()->a.preview(item));await(()->a.previewStarted,"downloaded voice did not actually synthesize",20000);ui(()->{a.preview(item);check(a.previewKey.isEmpty()&&!a.guard.held,"preview stop failed");});screenshot("voice-direct-installed.png");result.putInt("offlineVoices",a.items(language).size());result.putString("result","PASS: system settings button removed; download requested in-app through public setVoice API; stayed in app; no preview/focus on request; actual installed-data status detected; real newly downloaded voice preview/pause; reading preferences preserved");passed=true;}catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(activity!=null){final OfflineVoicesActivity a=activity;ui(a::finish);}}finish(passed?-1:0,result);}
}
